package com.argument.teachingtrial;
import com.argument.common.exception.*;
import com.argument.finalreview.*;
import com.argument.version.*;
import com.argument.version.port.VersionIdentity.Actor;
import com.argument.teaching.rules.TeachingExerciseType;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import static com.argument.adjudication.AdjudicationService.require;
import static com.argument.teachingtrial.TeachingAccess.*;

@Service @Profile("(local | test) & !prod") @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
public class TeachingWorkspaceService {
 final TeachingAccess access;private final FinalReviewRepository finals;private final TeachingSnapshot snapshots;private final TeachingTime clock;private final ObjectMapper mapper;
 public TeachingWorkspaceService(TeachingAccess access,FinalReviewRepository finals,TeachingSnapshot snapshots,TeachingTime clock,ObjectMapper mapper){this.access=access;this.finals=finals;this.snapshots=snapshots;this.clock=clock;this.mapper=mapper;}
 private ObjectNode base(Actor actor){var n=mapper.createObjectNode();VersionJson.stamp(n,actor.id(),VersionJson.now());return n;}
 private void append(String kind,ObjectNode n){access.store.insert(kind,n);}
 public ObjectNode overview(Actor supplied){var actor=access.fresh(supplied);boolean teacher=actor.role("TEACHER")&&actor.permission("COURSE_MANAGE"),student=actor.role("STUDENT")&&actor.permission("STUDENT_ANSWER_WORK"),creator=actor.role("TASK_CREATOR")&&actor.permission("TASK_CREATE");require(teacher||student||creator,ErrorCode.FORBIDDEN,"当前角色没有教学入口权限");var out=mapper.createObjectNode().put("mode","D_BRANCH_TRIAL").put("teamReviewRequired",true).put("teacherMode",teacher).put("studentMode",student).put("creatorMode",creator).putNull("courseTotalScore");for(String f:List.of("courses","assignments","standards","sourceGrants","students","teachers","sources"))out.putArray(f);var types=out.putArray("exerciseTypes");for(var t:TeachingExerciseType.values())types.addObject().put("code",t.name()).put("label",t.label());
  if(teacher){access.data.find("teachingCourse","teacherUserId",actor.id()).forEach(n->((ArrayNode)out.path("courses")).add(courseView(actor,n.path("id").asText())));access.data.find("teachingAssignment",null,null).stream().filter(a->actor.id().equals(a.path("teacherUserId").asText())).forEach(n->((ArrayNode)out.path("assignments")).add(n));access.data.find("teachingStandard","teacherUserId",actor.id()).forEach(n->((ArrayNode)out.path("standards")).add(n));access.data.find("teachingSourceGrant","teacherUserId",actor.id()).forEach(n->((ArrayNode)out.path("sourceGrants")).add(n));directory("STUDENT").forEach(n->((ArrayNode)out.path("students")).add(n));}
  if(student)for(var a:access.data.find("teachingAssignment",null,null)){try{access.studentAssignment(actor,a.path("id").asText());}catch(BusinessException e){continue;}var safe=a.deepCopy();safe.retain("id","name","courseId","classId","dueAt","answerOpensAt","maxAttempts","exerciseMode","exerciseType","status");((ArrayNode)out.path("assignments")).add(safe);}
  if(creator){directory("TEACHER").forEach(n->((ArrayNode)out.path("teachers")).add(n));for(var task:access.data.find("task","ownerUserId",actor.id()))for(var doc:access.data.find("taskDocument","taskId",task.path("id").asText()))for(var f:finals.versions(doc.path("id").asText()))if("IN_DATABASE".equals(f.path("status").asText()))((ArrayNode)out.path("sources")).addObject().put("finalVersionId",f.path("id").asText()).put("title",access.data.read("document",doc.path("documentId").asText()).path("title").asText()).put("versionNumber",f.path("versionNumber").asInt());access.data.find("teachingSourceGrant","createdById",actor.id()).forEach(n->((ArrayNode)out.path("sourceGrants")).add(n));}return out;
 }
 private List<ObjectNode> directory(String role){var list=new ArrayList<ObjectNode>();for(var user:access.data.find("user",null,null)){try{var a=access.fresh(new Actor(user.path("id").asText(),"",Set.of(),Set.of()));if(a.role(role))list.add(mapper.createObjectNode().put("id",a.id()).put("displayName",a.name()));}catch(BusinessException e){continue;}}return list;}
 public ObjectNode courseView(Actor actor,String id){var c=access.course(actor,id,"COURSE_MANAGE");var out=c.deepCopy();var cls=access.data.read("teachingClass",c.path("classId").asText());out.set("class",cls);var students=out.putArray("students");for(var m:access.data.find("teachingMembership","classId",cls.path("id").asText())){var n=m.deepCopy();n.put("displayName",access.data.read("user",m.path("studentUserId").asText()).path("displayName").asText());students.add(n);}return out;}
 @Transactional public ObjectNode createCourse(Actor supplied,String key,ObjectNode body){var actor=access.actor(supplied,"TEACHER","COURSE_MANAGE");fields(body,Set.of("name","className","studentUserIds"),Set.of());access.lock(actor);var cached=access.receipt(actor,"COURSE",key,body);if(cached!=null)return cached;String name=text(body,"name",200),className=text(body,"className",100);require(body.path("studentUserIds").isArray()&&body.path("studentUserIds").size()<=1000,ErrorCode.VALIDATION_ERROR,"班级最多 1000 名学生");var students=new HashSet<String>();for(var id:body.path("studentUserIds")){require(id.isTextual()&&students.add(VersionJson.uuid(id.asText())),ErrorCode.VALIDATION_ERROR,"学生 ID 无效或重复");access.actor(new Actor(id.asText(),"",Set.of(),Set.of()),"STUDENT","STUDENT_ANSWER_WORK");}var c=base(actor);var cls=base(actor);c.put("name",name).put("teacherUserId",actor.id()).put("classId",cls.path("id").asText()).put("status","DRAFT");cls.put("courseId",c.path("id").asText()).put("name",className).put("status","DRAFT");append("teachingCourse",c);append("teachingClass",cls);for(String student:students){var m=base(actor);m.put("classId",cls.path("id").asText()).put("studentUserId",student).put("status","ACTIVE");append("teachingMembership",m);}access.finish(actor,"COURSE",key,body,c);return c;}
 @Transactional public ObjectNode activateCourse(Actor supplied,String id,String key,int expected,ObjectNode body){var actor=access.actor(supplied,"TEACHER","COURSE_MANAGE");fields(body,Set.of("confirmed"),Set.of());require(body.path("confirmed").isBoolean()&&body.path("confirmed").asBoolean(),ErrorCode.VALIDATION_ERROR,"请确认开课");access.lock(actor);var c=access.course(actor,id,"COURSE_MANAGE");c=access.data.lock("teachingCourse",id);var cached=access.receipt(actor,"ACTIVATE:"+id,key,body);if(cached!=null)return cached;match(c,expected);require("DRAFT".equals(c.path("status").asText())&&!access.data.find("teachingMembership","classId",c.path("classId").asText()).isEmpty(),ErrorCode.CONFLICT,"课程须为草稿且至少有一名学生");var cls=access.data.lock("teachingClass",c.path("classId").asText());c.put("status","ACTIVE");touch(c,actor);cls.put("status","ACTIVE");touch(cls,actor);access.data.replace("teachingCourse",c);access.data.replace("teachingClass",cls);access.finish(actor,"ACTIVATE:"+id,key,body,c);return c;}
 @Transactional public ObjectNode deactivateMember(Actor supplied,String id,String key,int expected,ObjectNode body){var actor=access.actor(supplied,"TEACHER","COURSE_MANAGE");fields(body,Set.of("reason"),Set.of());text(body,"reason",1000);access.lock(actor);var member=access.data.read("teachingMembership",VersionJson.uuid(id));var cls=access.data.read("teachingClass",member.path("classId").asText());access.course(actor,cls.path("courseId").asText(),"COURSE_MANAGE");access.data.lock("teachingCourse",cls.path("courseId").asText());access.data.lock("teachingClass",cls.path("id").asText());member=access.data.lock("teachingMembership",id);var cached=access.receipt(actor,"REMOVE_MEMBER:"+id,key,body);if(cached!=null)return cached;match(member,expected);member.put("status","INACTIVE").put("reason",body.path("reason").asText());touch(member,actor);access.data.replace("teachingMembership",member);access.finish(actor,"REMOVE_MEMBER:"+id,key,body,member);return member;}
 @Transactional public ObjectNode grantSource(Actor supplied,String key,ObjectNode body){var actor=access.actor(supplied,"TASK_CREATOR","TASK_CREATE");fields(body,Set.of("finalVersionId","teacherUserId"),Set.of());access.lock(actor);String f=VersionJson.uuid(body.path("finalVersionId").asText()),teacher=VersionJson.uuid(body.path("teacherUserId").asText());var frozen=finals.snapshot(f);var doc=access.data.read("taskDocument",frozen.path("version").path("taskDocumentId").asText());access.versions.lockCase(doc.path("id").asText());var task=access.data.lock("task",doc.path("taskId").asText());require(actor.id().equals(task.path("ownerUserId").asText()),ErrorCode.FORBIDDEN,"只能授权本人任务的已入库成果");require("IN_DATABASE".equals(frozen.path("version").path("status").asText()),ErrorCode.FINAL_NOT_IN_DATABASE,"仅已入库成果可授权教学");access.actor(new Actor(teacher,"",Set.of(),Set.of()),"TEACHER","COURSE_DOCUMENT_VIEW");var cached=access.receipt(actor,"SOURCE_GRANT",key,body);if(cached!=null)return cached;require(access.data.find("teachingSourceGrant","teacherUserId",teacher).stream().noneMatch(g->f.equals(g.path("sourceFinalVersionId").asText())&&"ACTIVE".equals(g.path("status").asText())),ErrorCode.CONFLICT,"该教师已有本成果的有效授权");var g=base(actor);g.put("sourceFinalVersionId",f).put("teacherUserId",teacher).put("taskId",task.path("id").asText()).put("documentId",doc.path("documentId").asText()).put("title",access.data.read("document",doc.path("documentId").asText()).path("title").asText()).put("guideVersionId",frozen.path("version").path("guideVersionId").asText()).put("contentDigest",FinalReviewService.contentDigest(frozen)).put("status","ACTIVE");append("teachingSourceGrant",g);access.finish(actor,"SOURCE_GRANT",key,body,g);return g;}
 @Transactional public ObjectNode revokeSource(Actor supplied,String id,String key,int expected,ObjectNode body){var actor=access.actor(supplied,"TASK_CREATOR","TASK_CREATE");fields(body,Set.of("reason"),Set.of());text(body,"reason",1000);access.lock(actor);var g=access.data.lock("teachingSourceGrant",VersionJson.uuid(id));require(actor.id().equals(g.path("createdById").asText())&&actor.id().equals(access.data.read("task",g.path("taskId").asText()).path("ownerUserId").asText()),ErrorCode.FORBIDDEN,"只能撤销本人授权");var cached=access.receipt(actor,"REVOKE:"+id,key,body);if(cached!=null)return cached;match(g,expected);g.put("status","REVOKED").put("reason",body.path("reason").asText());touch(g,actor);access.data.replace("teachingSourceGrant",g);access.finish(actor,"REVOKE:"+id,key,body,g);return g;}
 private ObjectNode granted(Actor actor,String id){var g=access.data.read("teachingSourceGrant",VersionJson.uuid(id));require(actor.id().equals(g.path("teacherUserId").asText())&&"ACTIVE".equals(g.path("status").asText()),ErrorCode.FORBIDDEN,"没有此教学来源的有效授权");var f=finals.snapshot(g.path("sourceFinalVersionId").asText());require("IN_DATABASE".equals(f.path("version").path("status").asText())&&g.path("contentDigest").asText().equals(FinalReviewService.contentDigest(f)),ErrorCode.SOURCE_INCOMPLETE,"教学来源与授权摘要不匹配");return g;}
 @Transactional public ObjectNode createStandard(Actor supplied,String key,ObjectNode body){var actor=access.actor(supplied,"TEACHER","STANDARD_ANSWER_MANAGE");fields(body,Set.of("sourceGrantId","name"),Set.of());access.lock(actor);var cached=access.receipt(actor,"STANDARD",key,body);if(cached!=null)return cached;var g=granted(actor,body.path("sourceGrantId").asText());access.data.lock("teachingSourceGrant",g.path("id").asText());var n=makeStandard(actor,g,text(body,"name",200),null);access.finish(actor,"STANDARD",key,body,n);return n;}
 private ObjectNode makeStandard(Actor actor,ObjectNode g,String name,ObjectNode previous){var n=base(actor);var frozen=finals.snapshot(g.path("sourceFinalVersionId").asText());var v=frozen.path("version");var doc=access.data.read("taskDocument",v.path("taskDocumentId").asText());n.put("name",name).put("teacherUserId",actor.id()).put("sourceGrantId",g.path("id").asText()).put("sourceFinalVersionId",g.path("sourceFinalVersionId").asText()).put("documentId",g.path("documentId").asText()).put("guideVersionId",g.path("guideVersionId").asText()).put("seriesId",previous==null?n.path("id").asText():previous.path("seriesId").asText()).put("versionNumber",previous==null?1:access.data.find("teachingStandard","seriesId",previous.path("seriesId").asText()).stream().mapToInt(x->x.path("versionNumber").asInt()).max().orElse(0)+1).put("status","DRAFT");var content=snapshots.copy(frozen,n.path("id").asText());content.set("text",access.data.read("text",v.path("documentTextVersionId").asText()));content.set("scope",access.data.read("scope",v.path("annotationScopeId").asText()));content.set("guideVersion",access.data.read("guideVersion",v.path("guideVersionId").asText()));var labels=content.putArray("labels");boolean v12=Set.of("v1.2","1.2").contains(content.path("guideVersion").path("versionCode").asText());access.data.find("label","guideVersionId",v.path("guideVersionId").asText()).stream().filter(l->!v12||!"GM-C".equals(l.path("code").asText())).forEach(labels::add);content.set("graph",snapshots.graph(content));n.put("contentDigest",VersionJson.canonicalHash(content));append("teachingStandard",n);var holder=mapper.createObjectNode().put("id",n.path("id").asText());holder.set("snapshot",content);append("teachingStandardSnapshot",holder);return n;}
 public ObjectNode standard(Actor supplied,String id){var actor=access.actor(supplied,"TEACHER","STANDARD_ANSWER_MANAGE");var n=access.data.read("teachingStandard",VersionJson.uuid(id));require(actor.id().equals(n.path("teacherUserId").asText()),ErrorCode.FORBIDDEN,"只能读取本人标准版本");var out=mapper.createObjectNode();out.set("standard",n);out.set("snapshot",safeSnapshot(standardContent(id)));return out;}
 ObjectNode standardContent(String id){var s=(ObjectNode)access.data.read("teachingStandardSnapshot",id).path("snapshot");var n=access.data.read("teachingStandard",id);require(n.path("contentDigest").asText().equals(VersionJson.canonicalHash(s)),ErrorCode.SOURCE_INCOMPLETE,"标准快照摘要不匹配");return s;}
 public ObjectNode safeSnapshot(ObjectNode source){var s=source.deepCopy();var text=s.path("text").path("normalizedText").asText();var scope=s.path("scope");s.put("scopeText",text.substring(scope.path("startOffset").asInt(),scope.path("endOffset").asInt())).put("offsetBase",scope.path("startOffset").asInt());s.remove("text");return s;}
 @Transactional public ObjectNode publishStandard(Actor supplied,String id,String key,int expected,ObjectNode body){var actor=access.actor(supplied,"TEACHER","STANDARD_ANSWER_MANAGE");fields(body,Set.of("reason"),Set.of());text(body,"reason",1000);access.lock(actor);var n=(ObjectNode)standard(actor,id).path("standard");n=access.data.lock("teachingStandard",id);var cached=access.receipt(actor,"PUBLISH_STANDARD:"+id,key,body);if(cached!=null)return cached;match(n,expected);require("DRAFT".equals(n.path("status").asText()),ErrorCode.CONFLICT,"已发布标准不能原地覆盖，请新建修订版本");access.data.lock("teachingSourceGrant",n.path("sourceGrantId").asText());granted(actor,n.path("sourceGrantId").asText());snapshots.graph(standardContent(id));n.put("status","PUBLISHED").put("publishedAt",VersionJson.now()).put("reason",body.path("reason").asText());touch(n,actor);access.data.replace("teachingStandard",n);access.finish(actor,"PUBLISH_STANDARD:"+id,key,body,n);return n;}
 @Transactional public ObjectNode reviseStandard(Actor supplied,String id,String key,ObjectNode body){var actor=access.actor(supplied,"TEACHER","STANDARD_ANSWER_MANAGE");fields(body,Set.of("sourceGrantId","reason"),Set.of());text(body,"reason",1000);access.lock(actor);var old=(ObjectNode)standard(actor,id).path("standard");access.data.lock("teachingStandard",old.path("seriesId").asText());var cached=access.receipt(actor,"REVISE_STANDARD:"+id,key,body);if(cached!=null)return cached;require("PUBLISHED".equals(old.path("status").asText()),ErrorCode.CONFLICT,"仅已发布标准可追加修订版本");var g=granted(actor,body.path("sourceGrantId").asText());require(old.path("documentId").equals(g.path("documentId"))&&old.path("guideVersionId").equals(g.path("guideVersionId")),ErrorCode.CONFLICT,"修订必须保持文书及指南一致");var n=makeStandard(actor,g,old.path("name").asText(),old);n.put("revisionReason",body.path("reason").asText());access.data.replace("teachingStandard",n);access.finish(actor,"REVISE_STANDARD:"+id,key,body,n);return n;}
 @Transactional public ObjectNode createAssignment(Actor supplied,String key,ObjectNode body){var actor=access.actor(supplied,"TEACHER","ASSIGNMENT_MANAGE");fields(body,Set.of("name","courseId","standardId","exerciseMode","exerciseType","dueAt"),Set.of());access.lock(actor);var c=access.course(actor,body.path("courseId").asText(),"ASSIGNMENT_MANAGE");access.data.lock("teachingCourse",c.path("id").asText());var cached=access.receipt(actor,"ASSIGNMENT",key,body);if(cached!=null)return cached;var standard=(ObjectNode)standard(actor,body.path("standardId").asText()).path("standard");require("PUBLISHED".equals(standard.path("status").asText()),ErrorCode.CONFLICT,"作业须绑定已发布标准");require(Set.of("RELATION_GUIDED","FULL_CASE").contains(body.path("exerciseMode").asText())&&TeachingExerciseType.of(body.path("exerciseType").asText())!=null,ErrorCode.VALIDATION_ERROR,"未知教学模式或专项类型");date(body,"dueAt");var n=base(actor);n.put("name",text(body,"name",200)).put("courseId",c.path("id").asText()).put("classId",c.path("classId").asText()).put("teacherUserId",actor.id()).put("standardId",standard.path("id").asText()).put("standardDigest",standard.path("contentDigest").asText()).put("scoringRuleVersion",TeachingScoring.version()).put("exerciseMode",body.path("exerciseMode").asText()).put("exerciseType",body.path("exerciseType").asText()).put("dueAt",body.path("dueAt").asText()).put("status","DRAFT").putNull("answerOpensAt").put("maxAttempts",1);append("teachingAssignment",n);access.finish(actor,"ASSIGNMENT",key,body,n);return n;}
 @Transactional public ObjectNode updateAssignment(Actor supplied,String id,String key,int expected,ObjectNode body){var actor=access.actor(supplied,"TEACHER","ASSIGNMENT_MANAGE");fields(body,Set.of("name","dueAt"),Set.of());var a=access.lockAssignment(actor,id,true,"ASSIGNMENT_MANAGE");var cached=access.receipt(actor,"UPDATE_ASSIGNMENT:"+id,key,body);if(cached!=null)return cached;match(a,expected);require("DRAFT".equals(a.path("status").asText()),ErrorCode.LOCKED_RESOURCE,"已发布作业不可覆盖");date(body,"dueAt");a.put("name",text(body,"name",200)).put("dueAt",body.path("dueAt").asText());touch(a,actor);access.data.replace("teachingAssignment",a);access.finish(actor,"UPDATE_ASSIGNMENT:"+id,key,body,a);return a;}
 @Transactional public ObjectNode publishAssignment(Actor supplied,String id,String key,int expected,ObjectNode body){var actor=access.actor(supplied,"TEACHER","ASSIGNMENT_MANAGE");fields(body,Set.of("maxAttempts","answerOpensAt"),Set.of());var a=access.lockAssignment(actor,id,true,"ASSIGNMENT_MANAGE");var cached=access.receipt(actor,"PUBLISH_ASSIGNMENT:"+id,key,body);if(cached!=null)return cached;match(a,expected);require("DRAFT".equals(a.path("status").asText())&&"ACTIVE".equals(access.data.read("teachingCourse",a.path("courseId").asText()).path("status").asText()),ErrorCode.CONFLICT,"作业须为草稿且课程已开课");require(body.path("maxAttempts").isIntegralNumber()&&body.path("maxAttempts").canConvertToInt()&&body.path("maxAttempts").asInt()>=1&&body.path("maxAttempts").asInt()<=10,ErrorCode.VALIDATION_ERROR,"允许作答次数为 1–10");require(java.time.Instant.parse(a.path("dueAt").asText()).isAfter(clock.now()),ErrorCode.CONFLICT,"截止时间必须晚于当前时间");date(body,"answerOpensAt");var std=access.data.read("teachingStandard",a.path("standardId").asText());granted(actor,std.path("sourceGrantId").asText());var source=standardContent(std.path("id").asText());var dataset=snapshots.copy(source,id);for(String f:List.of("text","scope","guideVersion","labels"))dataset.set(f,source.get(f));dataset.set("graph",snapshots.graph(dataset));var holder=mapper.createObjectNode().put("id",id);holder.set("snapshot",dataset);append("teachingDataset",holder);a.put("datasetDigest",VersionJson.canonicalHash(dataset)).put("status","PUBLISHED").put("maxAttempts",body.path("maxAttempts").asInt()).put("answerOpensAt",body.path("answerOpensAt").asText()).put("publishedAt",VersionJson.now());touch(a,actor);access.data.replace("teachingAssignment",a);access.finish(actor,"PUBLISH_ASSIGNMENT:"+id,key,body,a);return a;}
 ObjectNode dataset(ObjectNode assignment){var s=(ObjectNode)access.data.read("teachingDataset",assignment.path("id").asText()).path("snapshot");require(assignment.path("datasetDigest").asText().equals(VersionJson.canonicalHash(s)),ErrorCode.SOURCE_INCOMPLETE,"作业固定数据摘要不匹配");return s;}
}
